class Solution {
  public long maxProfit(int[] prices, int[] strategy, int k) {
    int n = prices.length, half = k / 2;
    long[] priceSum = new long[n + 1], profitSum = new long[n + 1];
    for (int i = 0; i < n; i++) {
      priceSum[i + 1] = priceSum[i] + prices[i];
      profitSum[i + 1] = profitSum[i] + (long) strategy[i] * prices[i];
    }
    long bestGain = 0;
    for (int i = 0; i + k <= n; i++) {
      // the window turns into: half holds (0) followed by half sells (+price)
      long after = priceSum[i + k] - priceSum[i + half];
      long before = profitSum[i + k] - profitSum[i];
      bestGain = Math.max(bestGain, after - before);
    }
    return profitSum[n] + bestGain;
  }
}
